{
  "mechanisms": [
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "A constant bonus is added to the Stage 1 value of the action chosen on the previous trial to model choice perseverance.",
      "params": [
        {
          "name": "stickiness",
          "bounds": [0, 5]
        }
      ],
      "evidence": "q_eff_1 = q_stage1.copy()\n        if last_action_1 != -1:\n            q_eff_1[last_action_1] += stickiness",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value Decay",
      "description": "The values of all unchosen actions in both Stage 1 and Stage 2 decay towards zero at a constant rate.",
      "params": [
        {
          "name": "decay_rate",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage2[s2, 1-a2] *= (1.0 - decay_rate)\n\n        q_stage2[1-s2, :] *= (1.0 - decay_rate)\n\n        q_stage1[1-a1] *= (1.0 - decay_rate)",
      "expressible_in_slots": true
    }
  ]
}
